/* Media controls use actual audio playback events; waveform is decorative. */
(()=>{const thread=document.querySelector('#thread'),wrap=document.querySelector('#today-wrap'),welcome=document.querySelector('#welcome');welcome.dataset.cardId='card-1';function banner(){const active=!!document.querySelector('#messages .message');wrap.classList.remove('is-floating');wrap.hidden=active;if(wrap.parentElement!==welcome)welcome.append(wrap);}new MutationObserver(banner).observe(document.querySelector('#messages'),{childList:true});banner();
const time=n=>Number.isFinite(n)?String(Math.floor(n/60)).padStart(2,'0')+':'+String(Math.floor(n%60)).padStart(2,'0'):'--:--';
function paint(a){const p=a.closest('.voice-pill');if(!p)return;const b=p.querySelector('button');b.setAttribute('aria-label',a.paused?'播放录音':'暂停录音');b.textContent=a.paused?'▶':'Ⅱ';p.classList.toggle('playing',!a.paused);p.querySelector('.voice-time').textContent=time(a.currentTime>0&&!a.ended?a.currentTime:a.duration);}
document.addEventListener('click',async e=>{const b=e.target.closest('.voice-play');if(!b||b.disabled)return;const a=b.closest('.voice-pill').querySelector('audio');if(!a)return;if(!a.paused){a.pause();return;}document.querySelectorAll('audio').forEach(other=>{if(other!==a)other.pause()});try{await a.play()}catch{b.setAttribute('aria-label','播放失败，点击重试');b.closest('.voice-pill').querySelector('.voice-time').textContent='重试'}});
for(const event of ['loadedmetadata','durationchange','timeupdate','play','pause','ended'])document.addEventListener(event,e=>{if(event==='play'&&e.target.matches?.('audio'))document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause()});if(e.target.matches?.('.voice-pill audio'))paint(e.target)},true);
document.addEventListener('error',e=>{if(e.target.matches?.('.voice-pill audio')){const p=e.target.closest('.voice-pill');p.classList.remove('playing');p.querySelector('.voice-time').textContent='无法播放';p.querySelector('button').setAttribute('aria-label','录音无法播放')}},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('audio').forEach(a=>a.pause())});
new MutationObserver(()=>{if(document.querySelector('#app').dataset.route!=='home')document.querySelectorAll('audio').forEach(a=>a.pause())}).observe(document.querySelector('#app'),{attributes:true,attributeFilter:['data-route']});})();
